    // Compute head vector: average(EARR, EARL, NOS_) - NEC_
    Eigen::Vector3d head_avg = (_positions[idx_earr] + _positions[idx_earl] + _positions[idx_nos]) / 3.0;
    Eigen::Vector3d head_vec = head_avg - _positions[idx_nec];

