    if (norm_torso > 1e-6 && norm_head > 1e-6) {
      double angle = std::acos(std::clamp(u, -1.0, 1.0));
      _cervical_flex = static_cast<float>(angle * 180.0 / M_PI);
    } else {
      _cervical_flex = 0.0f;
    }
    
